  add("precalc", "pc1", 2, [{"type":"regular","q":"How does $g(x) = f(x) - 4$ differ from $f(x)$?","answer":"Shifted down 4 units","solution":"Subtracting a constant from the output shifts the graph vertically downward."},{"type":"regular","q":"What does $g(x) = f(x + 5)$ do to the graph of $f$?","answer":"Shifted left 5 units","solution":"Adding to the input shifts the graph horizontally to the left."},{"type":"regular","q":"Describe the transformation: $g(x) = 3f(x)$.","answer":"Vertical stretch by factor 3","solution":"Multiplying the output by 3 stretches the graph vertically."},{"type":"regular","q":"What does $g(x) = f(-x)$ do to the graph of $f$?","answer":"Reflected across the y-axis","solution":"Negating the input reflects the graph across the y-axis."},{"type":"regular","q":"Describe $g(x) = \\frac{1}{2}f(x)$.","answer":"Vertical shrink by factor $\\frac{1}{2}$","solution":"Multiplying the output by $\\frac{1}{2}$ compresses the graph vertically."},{"type":"regular","q":"Start with $f(x) = x^2$. Describe the graph of $g(x) = (x + 2)^2 - 3$.","answer":"Shifted left 2, down 3","solution":"$(x + 2)$ shifts left 2 and $-3$ shifts down 3."},{"type":"regular","q":"If $f(x) = \\sqrt{x}$, describe $g(x) = -\\sqrt{x} + 1$.","answer":"Reflected across x-axis, shifted up 1","solution":"The negative sign reflects across the x-axis, and $+1$ shifts up."},{"type":"regular","q":"If $f(x) = |x|$, describe $g(x) = 2|x - 3|$.","answer":"Shifted right 3, vertical stretch by factor 2","solution":"$(x - 3)$ shifts right 3 and multiplying by 2 stretches vertically."},{"type":"word","q":"A parabola $y = x^2$ is shifted right 4 units and up 2 units. Write the new equation.","answer":"$g(x) = (x - 4)^2 + 2$","solution":"Shift right 4 means replace $x$ with $x - 4$; shift up 2 means add 2."},{"type":"word","q":"A cost function $C(x) = 100 + 5x$ is doubled (to account for inflation) then increased by \\$50. Write the new function.","answer":"$g(x) = 2(100 + 5x) + 50 = 250 + 10x$","solution":"Doubling multiplies the output by 2; adding 50 shifts up by 50."},{"type":"word","q":"A temperature graph $T(h)$ shows temperature over hours. If the graph is reflected (time runs backward) and shifted up 5°, write $g(h)$ in terms of $T$.","answer":"$g(h) = T(-h) + 5$","solution":"Reflection across y-axis is $T(-h)$; shifting up 5 adds 5."},{"type":"word","q":"A profit function $P(x) = 3x - 20$ is compressed horizontally by a factor of 2 (time speeds up). Write the new function.","answer":"$g(x) = 3(2x) - 20 = 6x - 20$","solution":"Horizontal compression by factor 2 replaces $x$ with $2x$."},{"type":"word","q":"A sound intensity function is $I(t) = \\sin(t)$. The amplitude is halved and the function is shifted right $\\pi$. Write $g(t)$.","answer":"$g(t) = \\frac{1}{2}\\sin(t - \\pi)$","solution":"Halving amplitude multiplies by $\\frac{1}{2}$; shifting right $\\pi$ replaces $t$ with $t - \\pi$."},{"type":"word","q":"A population function $P(t) = 1000 \\cdot 2^t$ is reflected across the x-axis (hypothetically) and shifted up 500. Write $g(t)$.","answer":"$g(t) = -1000 \\cdot 2^t + 500$","solution":"Reflection across x-axis negates the output; shifting up 500 adds 500."}]);
